import static org.assertj.core.api.Assertions.*;
class PhoneHttpTest {
 @Test void actualApplicationRequiresBoundActorAndPrivateScopeAndNeverExposesProofPublicly()throws Exception{
  String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"native messaging harness supplies PostgreSQL");var generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);var rsa=generator.generateKeyPair();var ecGenerator=KeyPairGenerator.getInstance("EC");ecGenerator.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));var ec=ecGenerator.generateKeyPair();var executor=Executors.newVirtualThreadPerTaskExecutor();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.setExecutor(executor);String issuer="http://127.0.0.1:"+server.getAddress().getPort()+"/realms/offline";server.createContext("/",x->{byte[] body=EventCodec.JSON.writeValueAsBytes(Map.of("keys",List.of(new RSAKey.Builder((RSAPublicKey)rsa.getPublic()).keyID("synthetic").algorithm(JWSAlgorithm.RS256).keyUse(com.nimbusds.jose.jwk.KeyUse.SIGNATURE).build().toJSONObject())));x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,body.length);x.getResponseBody().write(body);x.close();});server.start();var properties=new HashMap<String,Object>();properties.put("APP_ENV","test");properties.put("NIGSON_SECURITY_ENABLED","true");properties.put("NIGSON_EVENTS_ENABLED","false");properties.put("NIGSON_JDBC_URL",url+"?currentSchema=experience");properties.put("NIGSON_DB_USER","nigson_experience_app");properties.put("NIGSON_DB_PASSWORD","mock-experience-runtime");properties.put("NIGSON_OIDC_ISSUER",issuer);properties.put("NIGSON_OIDC_JWKS",issuer+"/protocol/openid-connect/certs");properties.put("NIGSON_PRIVATE_PEER_CIDRS","127.0.0.1/32");properties.put("NIGSON_ACTOR_PUBLIC_KEYS",EventCodec.JSON.writeValueAsString(Map.of("active",Base64.getEncoder().encodeToString(ec.getPublic().getEncoded()))));properties.put("NIGSON_PHONE_CONSENT_ENABLED","true");properties.put("NIGSON_PHONE_CIPHER_REVISION","synthetic");properties.put("NIGSON_PHONE_HASH_KEY_VERSION","1");properties.put("NIGSON_PHONE_POLICY_VERSIONS","SYNTHETIC_HTTP_POLICY");byte[] hmac=new byte[32],cipher=new byte[32];Arrays.fill(hmac,(byte)7);Arrays.fill(cipher,(byte)9);properties.put("NIGSON_PHONE_LOCAL_HASH_KEY",Base64.getEncoder().encodeToString(hmac));properties.put("NIGSON_PHONE_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(cipher));properties.put("server.port","0");properties.put("logging.level.root","WARN");
  try(var app=new SpringApplicationBuilder(ExperienceApplication.class).properties(properties).run();var http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build()){
   String base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort();var actor=new ActorAssertion.Actor(UUID.randomUUID(),issuer,"synthetic-customer",null,Set.of("CUSTOMER"),Set.of(),null);String input="{\"channel\":\"SMS\",\"address\":\"+2348000000001\",\"policyVersion\":\"SYNTHETIC_HTTP_POLICY\",\"consentedPurposes\":[\"ORDER_UPDATES\"]}";String token=workload(rsa,issuer,"nigson-commerce","communication.create_WITH_SIGNED_CUSTOMER communication.verify_WITH_SIGNED_CUSTOMER communication.read_WITH_SIGNED_CUSTOMER communication.withdraw_WITH_SIGNED_CUSTOMER");UUID correlation=UUID.randomUUID();String path="/internal/v1/communication-destinations",assertion=assertion(ec,actor,"communication.create_WITH_SIGNED_CUSTOMER","POST",path,correlation,input);
   assertThat(send(http,base+path,"POST",input,token,null,correlation,"create").statusCode()).isEqualTo(401);
   var created=send(http,base+path,"POST",input,token,assertion,correlation,"create");assertThat(created.statusCode()).isEqualTo(201);assertThat(created.body()).doesNotContain("+2348000000001","ciphertext","policyVersion","code");var dto=EventCodec.JSON.readTree(created.body());UUID id=UUID.fromString(dto.path("id").asString());assertThat(dto.propertyNames()).containsExactlyInAnyOrder("id","channel","maskedAddress","status","version");assertThat(send(http,base+path,"POST",input.replace("ORDER_UPDATES","MARKETING"),token,assertion,correlation,"tampered").statusCode()).isEqualTo(401);assertThat(send(http,base+"/api/v1/me/communication-destinations","GET","",null,null,UUID.randomUUID(),null).statusCode()).isIn(401,403);
   var jdbc=app.getBean(org.springframework.jdbc.core.JdbcTemplate.class);UUID verification=jdbc.queryForObject("SELECT id FROM experience.destination_verification WHERE destination_id=?",UUID.class,id);UUID job=UUID.nameUUIDFromBytes(("contact-verification:"+verification).getBytes(java.nio.charset.StandardCharsets.US_ASCII));String contextPath="/internal/v1/communication-verifications/"+verification+"/notification-context",jobBody=EventCodec.JSON.writeValueAsString(Map.of("jobId",job));String worker=workload(rsa,issuer,"nigson-integration","notification.read");var context=send(http,base+contextPath,"POST",jobBody,worker,null,UUID.randomUUID(),null);assertThat(context.statusCode()).isEqualTo(200);String code=EventCodec.JSON.readTree(context.body()).path("code").asString();assertThat(code).matches("[0-9]{6}");assertThat(send(http,base+contextPath,"POST",jobBody,token,null,UUID.randomUUID(),null).statusCode()).isEqualTo(401);
   String confirmPath=path+"/"+id+"/verification",confirmBody=EventCodec.JSON.writeValueAsString(Map.of("code",code,"version",0));UUID confirmCorrelation=UUID.randomUUID();var confirmed=send(http,base+confirmPath,"POST",confirmBody,token,assertion(ec,actor,"communication.verify_WITH_SIGNED_CUSTOMER","POST",confirmPath,confirmCorrelation,confirmBody),confirmCorrelation,"confirm");assertThat(confirmed.statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(confirmed.body()).path("status").asString()).isEqualTo("ACTIVE");assertThat(jdbc.queryForObject("SELECT code_ciphertext FROM experience.destination_verification WHERE id=?",byte[].class,verification)).isNull();assertThat(send(http,base+contextPath,"POST",jobBody,worker,null,UUID.randomUUID(),null).statusCode()).isEqualTo(422);
   String eligibilityBody=EventCodec.JSON.writeValueAsString(Map.of("partyId",actor.party(),"channel","SMS","purpose","ORDER_UPDATES"));String eligibilityToken=workload(rsa,issuer,"nigson-integration","consent.read");var eligibility=send(http,base+"/internal/v1/communication-eligibility","POST",eligibilityBody,eligibilityToken,null,UUID.randomUUID(),null);assertThat(eligibility.statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(eligibility.body()).path("eligible").asBoolean()).isTrue();assertThat(send(http,base+"/internal/v1/communication-eligibility","POST",eligibilityBody,worker,null,UUID.randomUUID(),null).statusCode()).isEqualTo(401);
   String withdrawPath=path+"/"+id+"/withdrawal",withdrawBody="{\"version\":1}";UUID withdrawal=UUID.randomUUID();assertThat(send(http,base+withdrawPath,"POST",withdrawBody,token,assertion(ec,actor,"communication.withdraw_WITH_SIGNED_CUSTOMER","POST",withdrawPath,withdrawal,withdrawBody),withdrawal,"withdraw").statusCode()).isEqualTo(204);assertThat(jdbc.queryForObject("SELECT status FROM experience.communication_destination WHERE id=?",String.class,id)).isEqualTo("UNSUBSCRIBED");
  }finally{server.stop(0);executor.shutdownNow();}
 }
 String workload(KeyPair rsa,String issuer,String client,String scope)throws Exception{var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).keyID("synthetic").build(),new JWTClaimsSet.Builder().issuer(issuer).subject("synthetic-workload").audience("nigson-experience").claim("typ","Bearer").claim("client_id",client).claim("azp",client).claim("scope",scope).issueTime(Date.from(Instant.now())).expirationTime(Date.from(Instant.now().plusSeconds(120))).build());jwt.sign(new RSASSASigner((RSAPrivateKey)rsa.getPrivate()));return jwt.serialize();}
 String assertion(KeyPair ec,ActorAssertion.Actor actor,String scope,String method,String path,UUID correlation,String body)throws Exception{var actual=new ActorAssertion.Actor(actor.party(),actor.identityIssuer(),actor.identitySubject(),actor.organization(),actor.roles(),Set.of(scope),actor.mfaAt());var binding=new ActorAssertion.Binding("experience",scope,method,path,correlation,ActorAssertion.Binding.bodyHash(body.getBytes(java.nio.charset.StandardCharsets.UTF_8)));var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID("active").type(new JOSEObjectType("nigson-actor+jwt")).build(),ActorAssertion.claims(actual,binding,Instant.now()));jwt.sign(new ECDSASigner((ECPrivateKey)ec.getPrivate()));return jwt.serialize();}
 HttpResponse<String> send(HttpClient http,String url,String method,String body,String token,String actor,UUID correlation,String key)throws Exception{var request=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("X-Correlation-ID",correlation.toString());if(token!=null)request.header("Authorization","Bearer "+token);if(actor!=null)request.header("X-Nigson-Actor",actor);if(key!=null)request.header("Idempotency-Key",key);if(!method.equals("GET"))request.header("Content-Type","application/json");return http.send(request.method(method,body.isEmpty()?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
}
